def monomial_coefficients(alpha):
 # (-1)^l C(n,l) C(n+l,l), generated by an exact integer recurrence.
 M=max(alpha);scale=10**40;coeff=[0]*(M+1)
 for n,q in sorted(alpha.items()):
  assert n%2==0 and scale%q.denominator==0
  v=q.numerator*(scale//q.denominator);term=1
  for l in range(n+1):
   coeff[l]+=v*term
   if l<n:
    numerator=-term*(n-l)*(n+l+1);denominator=(l+1)**2;assert numerator%denominator==0;term=numerator//denominator
 # Exact Horner substitution v -> 1-v checks the entire even parity identity.
 reflected=[]
 for c in reversed(coeff):
  reflected=([reflected[0]+c]+[reflected[i]-reflected[i-1] for i in range(1,len(reflected))]+[-reflected[-1]]) if reflected else [c]
 assert reflected==coeff
 result=[F(x,scale) for x in coeff]
 for l in sorted(set([0,1,min(17,M),min(96,M),M//2,M])):
  assert result[l]==sum(alpha[n]*(-1)**l*math.comb(n,l)*math.comb(n+l,l) for n in alpha if n>=l)
 return result
