 src=replace(src,'assert all(a[l]==(-1)**l*sum(a[j]*math.comb(j,l) for j in range(l,M+1)) for l in range(M+1))','assert all(n%2==0 for n in alpha) # Full coefficient parity checked in the integer recurrence helper.')
